import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"占位符参考","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/placeholders.md","filePath":"modules/corelib/placeholders.md","lastUpdated":0}`),a={name:`modules/corelib/placeholders.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="占位符参考" tabindex="-1">占位符参考 <a class="header-anchor" href="#占位符参考" aria-label="Permalink to “占位符参考”">​</a></h1><p>CoreLib 在 Action 里能直接使用的内置变量和内联 Token 如下, 附使用示例</p><p>前置说明: CoreLib 不注册 PlaceholderAPI 扩展, 动作上下文变量由它自己提供, 所有模块执行 Action 时都能用</p><h2 id="动作上下文变量" tabindex="-1">动作上下文变量 <a class="header-anchor" href="#动作上下文变量" aria-label="Permalink to “动作上下文变量”">​</a></h2><p>Action 触发时, CoreLib 会自动把这些内置变量注入上下文. 任何模块的 Action 配置里都能用 <code>%variable%</code> 写法引用:</p><h3 id="内置变量" tabindex="-1">内置变量 <a class="header-anchor" href="#内置变量" aria-label="Permalink to “内置变量”">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%player%</code></td><td>玩家名</td><td><code>Steve</code></td></tr><tr><td><code>%player_name%</code></td><td>玩家名 (和 <code>%player%</code> 一样)</td><td><code>Steve</code></td></tr><tr><td><code>%player_uuid%</code></td><td>玩家的 UUID</td><td><code>550e8400-e29b-...</code></td></tr><tr><td><code>%player_world%</code></td><td>玩家所在世界的名字</td><td><code>world</code></td></tr><tr><td><code>%player_x%</code></td><td>玩家的 X 坐标 (浮点数)</td><td><code>128.5</code></td></tr><tr><td><code>%player_y%</code></td><td>玩家的 Y 坐标 (浮点数)</td><td><code>64.0</code></td></tr><tr><td><code>%player_z%</code></td><td>玩家的 Z 坐标 (浮点数)</td><td><code>256.0</code></td></tr><tr><td><code>%phase%</code></td><td>当前动作阶段</td><td><code>success</code></td></tr></tbody></table><p>注意: 上面这些玩家变量只在动作上下文里有玩家时才会注入. 变量名匹配不区分大小写; 调用方已经注入同名变量时, 以调用方给的值为准</p><h3 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to “使用示例”">​</a></h3><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;&lt;green&gt;恭喜 %player_name%，操作成功！&lt;/green&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;run_command_as_console command=&quot;say %player_name% 在 %player_world% 完成了操作&quot;&#39;</span></span></code></pre></div><h2 id="内联-token" tabindex="-1">内联 Token <a class="header-anchor" href="#内联-token" aria-label="Permalink to “内联 Token”">​</a></h2><p>CoreLib 还支持 <code>&lt;show_item&gt;</code> 内联 Token (写进文本即被替换的特殊标记). Action 上下文里设了 <code>show_item</code> 后, 聊天消息会显示物品悬浮提示, 可直接观察验证</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;你获得了 &lt;show_item&gt;！&quot;&#39;</span></span></code></pre></div><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to “说明”">​</a></h2><ul><li>各子模块 (Forge, Gem, Skills 等) 会在自己的 Action 上下文里注入额外变量, 详见各模块的占位符文档</li><li>动作上下文变量和 PlaceholderAPI 占位符是两套独立的系统, 格式一样但解析时机不同</li><li>PlaceholderAPI 占位符在 Action 里同样能用 (需要装 PlaceholderAPI)</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};